import org.junit.platform.launcher.TestPlan;
import org.junit.platform.commons.util.PackageUtils;

public class Foo {
  public void foo() {
    new TestPlan().removeInternal(null); // @API(status = INTERNAL, since = "6.1")
    PackageUtils.getAttribute(String.class, "foo"); // @API(status = INTERNAL, since = "1.0")
  }
}

class Sibling {
    @API(status = INTERNAL)
    static void internal() {}
}

public class Foo {
  public void foo() {
    new Sibling.internal();
  }
}

import net.sourceforge.pmd.lang.java.rule.design.internalapiusage.Internal;

public class Foo {
  public void foo() {
    Internal.internal();
    ClassLevelInternal.internal();
  }
}

package net.sourceforge.pmd.lang.java.rule.design.internalapiusage;

public class Foo {
  void bar() {
    Internal.internalForThisPackage();
    Internal.internalForOtherPackage();
  }
}

public class Foo {
  class Child {
      @VisibleForTesting
      static void internal() {}
  }
 public void foo() {
    new Child().internal();
 }
}

package net.sourceforge.pmd.lang.java.rule.design.internalapiusage;

public class Foo {
  public void foo() {
    Internal.visibleForTesting();
  }
}

public class Foo {
  class Child {
      @TestOnly
      static void testOnly() {}
  }
 public void foo() {
    new Child().testOnly();
 }
}

package net.sourceforge.pmd.lang.java.rule.design.internalapiusage;

public class Foo {
  public void foo() {
    Internal.testOnly();
  }
}

package net.sourceforge.pmd.lang.java.rule.design.internalapiusage;

import org.junit.jupiter.api.Test;

public class Foo {
  @Test
  void theTest() {
    Internal.visibleForTesting();
    Internal.testOnly();
  }
  void helper() {
    Internal.testOnly();
  }
}
